// Generate the better-auth tables into server/db/schema.auth.ts via the CLI,
// then re-export them from server/db/schema.ts.
//
// LAW: better-auth schemas are ALWAYS generated by the CLI, never hand-written.
//   1. `bunx auth generate --config scripts/auth.config.ts` (the plugin mirror
//      of server/domains/auth/auth.service.ts)
//   2. post-process: uuidv7() id defaults, apikey FK the CLI omits,
//     withTimezone timestamps, repo formatting, drop the CLI's relations block
//      (the app defines its own via defineRelations in schema.ts)
//   3. write server/db/schema.auth.ts; schema.ts re-exports it — no splicing,
//      no generated markers, no way to hand-edit by accident
//
// Usage: bun run gen:auth  (CI re-runs this and fails on any diff — drift guard)
import { execSync } from 'node:child_process'
import { readFileSync, writeFileSync } from 'node:fs'

const OUT = '/tmp/tandem-auth-schema.ts'
execSync(`bunx auth generate --config scripts/auth.config.ts --output ${OUT} -y`, { stdio: 'pipe' })
let gen = readFileSync(OUT, 'utf8')

// --- post-process ---
// ids: TEXT columns minted at runtime by better-auth's generateId (our uuidv7).
// The CLI's uuid()/gen_random_uuid() column types+defaults are normalized away:
// uuid-typed ids would break the text-id FK contract with the domain tables,
// and uuidv7() as a DB default only exists on PG18 (local/e2e run 17).
gen = gen.replace(/uuid\((['"])([a-z_]+)\1\)/g, "text('$2')")
gen = gen.replaceAll('.default(sql`pg_catalog.gen_random_uuid()`)', '')
gen = gen.replaceAll('.default(sql`gen_random_uuid()`)', '')
gen = gen.replaceAll('.default(sql`uuidv7()`)', '')
// FK the generator omits: apikey.referenceId -> user
gen = gen.replace("referenceId: text('reference_id').notNull(),",
  "referenceId: text('reference_id').notNull().references(() => user.id, { onDelete: 'cascade' }),")
// timezone-aware timestamps (the whole app uses timestamptz)
gen = gen.replace(/timestamp\('([a-z_]+)'\)/g, "timestamp('$1', { withTimezone: true })")

// drop the relations part — the app owns relations via defineRelations
const relIdx = gen.indexOf('export const authRelations')
if (relIdx > -1) gen = gen.slice(0, relIdx)

// repo formatting: drop import lines + blanks, normalize indent/quotes
let body = gen.split('\n').filter(l => !l.startsWith('import') && l.trim() !== '').join('\n')
body = body.replaceAll('\t', '  ')
body = body.replace(/"/g, "'")
body = body.replace(/ {2,}/g, '  ')
body = body.replaceAll('()=> ', '()=>')
body = body.replaceAll(' )', ')')
body = body.replaceAll('});', ' })')
body = body.replaceAll(String.raw`.$onUpdate(() => /* @__PURE__ */ new Date())`, '')

const header = `// GENERATED by the better-auth CLI — regenerate with \`bun run gen:auth\`.
// NEVER hand-edit: CI reruns the generator and fails on any diff.
// (script: scripts/gen-auth-schema.ts; config mirror: scripts/auth.config.ts)
import { pgTable, text, timestamp, boolean, integer, index } from 'drizzle-orm/pg-core'

`
writeFileSync('server/db/schema.auth.ts', header + body.trimEnd() + '\n')
console.log('server/db/schema.auth.ts regenerated from better-auth config')
